UPDATE `quest_template_locale` SET `QuestDescription` = 'Штормград отвернулся от нас. Злобный ветер несчастий носится по равнинам Западного Края. Это была моя родина, и я не отвернусь от местных жителей, решивших остаться здесь. Мы, бывшие фермеры, намерены постоять за себя.$b$bТвое задание, если ты за него возьмешься, будет состоять в том, чтобы патрулировать луга Западного Края. Выследи и убей мерзких гноллов, которые, похоже, действуют заодно с ворами из Мертвых копей. Принеси мне 8 лап гноллов, и я вознагражу тебя за проявленное мужество.' WHERE `ID` = 102 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Штормград отвернулся от нас. Злобный ветер несчастий носится по равнинам Западного Края. Это была моя родина, и я не отвернусь от местных жителей, решивших остаться здесь. Мы, бывшие фермеры, намерены постоять за себя.$b$bТвое задание, если ты за него возьмешься, будет состоять в том, чтобы патрулировать луга Западного Края. Выследи и убей мерзких гноллов, которые, похоже, действуют заодно с ворами из Мертвых копей. Принеси мне 8 лап гноллов, и я вознагражу тебя за проявленное мужество.' AS BINARY)));
