UPDATE `quest_template_locale` SET `QuestDescription` = 'Гад такой! Бросил меня ради своего клятого похода! Понимаете ли, "Свет превыше всего, ибо он единственная наша защита от нежити!"$B$BА как же дети?! А я?! Много ночей я терпеливо ждала его... я всегда была второй после его чертового долга!$B$BИ посмотрите, $n, теперь на плоды борьбы за "справедливость"! Он мертв, а на меня обрушилось все то, чему он пытался помешать!$B$BВозьмите этот хлам и положите на его могилу в Гробнице. Мне не нужен больше этот мусор... и он сам тоже!' WHERE `ID` = 264 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Гад такой! Бросил меня ради своего клятого похода! Понимаете ли, "Свет превыше всего, ибо он единственная наша защита от нежити!"$B$BА как же дети?! А я?! Много ночей я терпеливо ждала его... я всегда была второй после его чертового долга!$B$BИ посмотрите, $n, теперь на плоды борьбы за "справедливость"! Он мертв, а на меня обрушилось все то, чему он пытался помешать!$B$BВозьмите этот хлам и положите на его могилу в Гробнице. Мне не нужен больше этот мусор... и он сам тоже!' AS BINARY)));
