UPDATE `quest_template_locale` SET `QuestDescription` = 'Верховный маг огромной силы отвечает за реактивацию энергетического узла. Они уже далеко зашли, так что единственный способ их остановить – это убить его. Это будет тяжело – безусловно, его защищают многочисленные маги и охранники. $b$bВам надо пойти и разобраться с ним, быстро. Когда он будет мертв, принесите мне его посох. Идите немедленно.', `QuestCompletionLog` = '' WHERE `ID` = 480 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Верховный маг огромной силы отвечает за реактивацию энергетического узла. Они уже далеко зашли, так что единственный способ их остановить – это убить его. Это будет тяжело – безусловно, его защищают многочисленные маги и охранники. $b$bВам надо пойти и разобраться с ним, быстро. Когда он будет мертв, принесите мне его посох. Идите немедленно.' AS BINARY)) OR NOT (CAST(`QuestCompletionLog` AS BINARY) <=> CAST('' AS BINARY)));
