UPDATE `quest_template_locale` SET `QuestDescription` = 'Ах, еще один мерзкий день на мельнице Таррен. От этого чистого воздуха у меня сразу портится настроение, $n.$b$bЧем скорее мы заразим здешних людей, тем лучше. Я провожу исследования различных смертоносных веществ, чтобы использовать их в моих составах, но собрать все времени не хватило.$B$BЕсли ты хочешь принести пользу, добудь для меня следующее: 10 языков серых медведей и очень редкую и труднодоступную лимфу паука-охотника. Медведи и пауки-охотники живут рядом с мельницей Таррен.' WHERE `ID` = 496 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Ах, еще один мерзкий день на мельнице Таррен. От этого чистого воздуха у меня сразу портится настроение, $n.$b$bЧем скорее мы заразим здешних людей, тем лучше. Я провожу исследования различных смертоносных веществ, чтобы использовать их в моих составах, но собрать все времени не хватило.$B$BЕсли ты хочешь принести пользу, добудь для меня следующее: 10 языков серых медведей и очень редкую и труднодоступную лимфу паука-охотника. Медведи и пауки-охотники живут рядом с мельницей Таррен.' AS BINARY)));
