UPDATE `quest_template_locale` SET `QuestDescription` = 'Вождь послал нас с ребятами, чтобы добыть кое-что из Дарнхольда и разведать, что представляет собой так называемый Синдикат.$b$bМы пошли к Дарнхольду, поглядели, что к чему, тут на нас и напал большой отряд людей. Мы бились изо всех сил, но они сильно превосходили нас числом. В конце концов нескольких из нас взяли в плен, но мне удалось сбежать.$b$bДарнхольд находится на юго-востоке отсюда, по ту сторону реки. Там держат Друлла и Тог\'тара, освободи их.' WHERE `ID` = 498 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Вождь послал нас с ребятами, чтобы добыть кое-что из Дарнхольда и разведать, что представляет собой так называемый Синдикат.$b$bМы пошли к Дарнхольду, поглядели, что к чему, тут на нас и напал большой отряд людей. Мы бились изо всех сил, но они сильно превосходили нас числом. В конце концов нескольких из нас взяли в плен, но мне удалось сбежать.$b$bДарнхольд находится на юго-востоке отсюда, по ту сторону реки. Там держат Друлла и Тог\'тара, освободи их.' AS BINARY)));
