UPDATE `quest_template_locale` SET `QuestDescription` = 'Я получил сообщение, что группа нежити спряталась и готовит атаку против нас. Вооруженные этой информацией, мы можем повернуть все другой стороной и напасть первыми, подавив их планы в самом зародыше. $b$bК сожалению, моя информация весьма обрывочная. Говорят, они скрываются в месте, называемом Погибель Берена. Точное местонахождение неизвестно, но, похоже, это пещера где-то в холмах, недалеко от участка, занятого даларанскими волшебниками. $b$bЯ доверяю вашей изобретательности. Отыщите их и нанесите им поражение.', `QuestCompletionLog` = '' WHERE `ID` = 516 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Я получил сообщение, что группа нежити спряталась и готовит атаку против нас. Вооруженные этой информацией, мы можем повернуть все другой стороной и напасть первыми, подавив их планы в самом зародыше. $b$bК сожалению, моя информация весьма обрывочная. Говорят, они скрываются в месте, называемом Погибель Берена. Точное местонахождение неизвестно, но, похоже, это пещера где-то в холмах, недалеко от участка, занятого даларанскими волшебниками. $b$bЯ доверяю вашей изобретательности. Отыщите их и нанесите им поражение.' AS BINARY)) OR NOT (CAST(`QuestCompletionLog` AS BINARY) <=> CAST('' AS BINARY)));
