UPDATE `quest_template_locale` SET `QuestDescription` = 'Внимание: вооружены и очень опасны!$b$bСледующие люди из Хилсбрада объявлены вне закона, и верховный палач Дарталия предлагает награду за их головы:$b$bКлерк Гораций Белоконь. Разыскивается за убийство стража смерти Томма.$b$BГорожанин Вилкс. Разыскивается за убийство аптекаря Эли.$b$BШахтер Хакетт. Разыскивается за убийство стража смерти Фрая.$b$BФермерша Калаба. Разыскивается за нападение из засады на караван с припасами из Подгорода.$b$bВсе перечисленные преступники скрываются, и найти их нелегко. Награда будет выдана при предъявлении доказательств их смерти.' WHERE `ID` = 567 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Внимание: вооружены и очень опасны!$b$bСледующие люди из Хилсбрада объявлены вне закона, и верховный палач Дарталия предлагает награду за их головы:$b$bКлерк Гораций Белоконь. Разыскивается за убийство стража смерти Томма.$b$BГорожанин Вилкс. Разыскивается за убийство аптекаря Эли.$b$BШахтер Хакетт. Разыскивается за убийство стража смерти Фрая.$b$BФермерша Калаба. Разыскивается за нападение из засады на караван с припасами из Подгорода.$b$bВсе перечисленные преступники скрываются, и найти их нелегко. Награда будет выдана при предъявлении доказательств их смерти.' AS BINARY)));
