UPDATE `quest_template_locale` SET `QuestDescription` = 'Хочешь попробовать напиток, придуманный Чэнем? Ах, до чего же хорош! Чэнь передал рецепт моему наставнику, ну а он – мне. Только для него понадобится несколько компонентов. Но он того стоит!$b$bПринеси мне 5 клыков равнинного льва, 5 почек долгонога и 1 рог рокочущей ящерицы. Из них выйдет прекрасный портер.$B$BВсе эти составляющие нетрудно отыскать в Степях.', `QuestCompletionLog` = '' WHERE `ID` = 821 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Хочешь попробовать напиток, придуманный Чэнем? Ах, до чего же хорош! Чэнь передал рецепт моему наставнику, ну а он – мне. Только для него понадобится несколько компонентов. Но он того стоит!$b$bПринеси мне 5 клыков равнинного льва, 5 почек долгонога и 1 рог рокочущей ящерицы. Из них выйдет прекрасный портер.$B$BВсе эти составляющие нетрудно отыскать в Степях.' AS BINARY)) OR NOT (CAST(`QuestCompletionLog` AS BINARY) <=> CAST('' AS BINARY)));
