UPDATE `quest_template_locale` SET `QuestDescription` = 'Отличный напиток, а? $b$bЯ научился у Чэня еще одному рецепту. Хочешь узнать? Много времени он не отнимает, а в жизни пригодится. $b$bПринеси мне 5 грозовых желез любых грозошкуров, 1 слюнную железу грозового змея от больших грозовых змеев и печень кодо от любого из кодо Степей.$B$BВставляет – не то слово. Это эль трогга, о котором я уже говорил.', `QuestCompletionLog` = '' WHERE `ID` = 822 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Отличный напиток, а? $b$bЯ научился у Чэня еще одному рецепту. Хочешь узнать? Много времени он не отнимает, а в жизни пригодится. $b$bПринеси мне 5 грозовых желез любых грозошкуров, 1 слюнную железу грозового змея от больших грозовых змеев и печень кодо от любого из кодо Степей.$B$BВставляет – не то слово. Это эль трогга, о котором я уже говорил.' AS BINARY)) OR NOT (CAST(`QuestCompletionLog` AS BINARY) <=> CAST('' AS BINARY)));
