UPDATE `quest_template_locale` SET `LogDescription` = 'Ганн Каменное Копье попросил вас убить 15 бейл\'данских землекопов и 5 бейл\'данских старшин.$b$bПринесите Ганну Каменному Копью записи Хазгорма.', `QuestDescription` = 'Ныне я брожу по дорогам родного края в одиночестве.$b$bДворфы Бейл Модана не чтят моих границ. Они постоянно устраивают взрывы, после которых остаются огромные ямы, а шумные механизмы разрывают мои холмы. Земли, некогда приютившие и питавшие мое племя, захвачены вредоносными дворфами.$B$BВсе попытки решить дело миром провалились. Пришло время для решительных действий.$B$BВыгони дворфов из раскопа в Бейл Модане и принеси мне записи Хазгорма, их главаря.' WHERE `ID` = 843 AND `locale` = 'ruRU' AND (NOT (CAST(`LogDescription` AS BINARY) <=> CAST('Ганн Каменное Копье попросил вас убить 15 бейл\'данских землекопов и 5 бейл\'данских старшин.$b$bПринесите Ганну Каменному Копью записи Хазгорма.' AS BINARY)) OR NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Ныне я брожу по дорогам родного края в одиночестве.$b$bДворфы Бейл Модана не чтят моих границ. Они постоянно устраивают взрывы, после которых остаются огромные ямы, а шумные механизмы разрывают мои холмы. Земли, некогда приютившие и питавшие мое племя, захвачены вредоносными дворфами.$B$BВсе попытки решить дело миром провалились. Пришло время для решительных действий.$B$BВыгони дворфов из раскопа в Бейл Модане и принеси мне записи Хазгорма, их главаря.' AS BINARY)));
