UPDATE `quest_template_locale` SET `QuestDescription` = 'Ой! $b$bКак видишь, у меня сегодня приключилась неприятность! Утром из Пиратской бухты пришла поставка. И какая! Никогда не видел столько ящиков. Я хотел побыстрее закончить, поэтому поднимал больше, чем следовало. В конце концов все рухнуло на землю.$B$BНе успел я оглянуться, как эта тварь, Безумный Магглиш, схватил бутылку портвейна 99-летней выдержки и бросился наутек. Я гнался за ним до самых Пещер Стенаний, но внутрь я не ходок.$B$BМожет, тебе хватит пороху, чтобы найти его?' WHERE `ID` = 959 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Ой! $b$bКак видишь, у меня сегодня приключилась неприятность! Утром из Пиратской бухты пришла поставка. И какая! Никогда не видел столько ящиков. Я хотел побыстрее закончить, поэтому поднимал больше, чем следовало. В конце концов все рухнуло на землю.$B$BНе успел я оглянуться, как эта тварь, Безумный Магглиш, схватил бутылку портвейна 99-летней выдержки и бросился наутек. Я гнался за ним до самых Пещер Стенаний, но внутрь я не ходок.$B$BМожет, тебе хватит пороху, чтобы найти его?' AS BINARY)));
