UPDATE `quest_template_locale` SET `QuestDescription` = 'Аругал по-прежнему сидит в крепости Темного Клыка. Мы не можем считать Серебряный бор стратегическим оплотом Темной Госпожи до тех пор, пока Аругал жив. $b$bЯ позабочусь о том, чтобы искоренить его магию, $n. Но сделать так, чтобы Аругал встретил заслуженную смерть – это я оставляю вам. $b$bОтправляйтесь в крепость Темного Клыка и положите конец скверным деяниям Аругала раз и навсегда. И принесите мне голову этого злодея!' WHERE `ID` = 1014 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Аругал по-прежнему сидит в крепости Темного Клыка. Мы не можем считать Серебряный бор стратегическим оплотом Темной Госпожи до тех пор, пока Аругал жив. $b$bЯ позабочусь о том, чтобы искоренить его магию, $n. Но сделать так, чтобы Аругал встретил заслуженную смерть – это я оставляю вам. $b$bОтправляйтесь в крепость Темного Клыка и положите конец скверным деяниям Аругала раз и навсегда. И принесите мне голову этого злодея!' AS BINARY)));
