UPDATE `quest_template_locale` SET `QuestDescription` = 'Готовясь к нападению на крепость Темного Клыка, мы отправили на разведку двух стражей смерти. Они не возвращаются вот уже много дней, но без их отчета нам не организовать успешного нападения!$b$bИтак, вот твое задание, $n. Отправляйся в крепость Темного Клыка на юге и найди стражей смерти Адаманта и Винсента. Найди их и помоги им, если сможешь.$b$bЭто очень опасное и важное задание, $n. Не подведи нас.' WHERE `ID` = 1098 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Готовясь к нападению на крепость Темного Клыка, мы отправили на разведку двух стражей смерти. Они не возвращаются вот уже много дней, но без их отчета нам не организовать успешного нападения!$b$bИтак, вот твое задание, $n. Отправляйся в крепость Темного Клыка на юге и найди стражей смерти Адаманта и Винсента. Найди их и помоги им, если сможешь.$b$bЭто очень опасное и важное задание, $n. Не подведи нас.' AS BINARY)));
