UPDATE `quest_template_locale` SET `QuestDescription` = 'Пока Наралекс погружался в свои кошмары все глубже, из-под Степей в Пещеры Стенаний пришли какие-то странные животные.$b$bЭти искаженные существа наделены странными, потусторонними силами. В то время как зло в их природе, я уверен, что из их существования можно извлечь некоторую пользу здесь в Калимдоре. Я верю, что из их кожи наши кожевники смастерят что-нибудь стоящее.$b$bЕсли эта задача тебе по вкусу, отправляйся в пещеры и принеси мне немного искаженных шкур.' WHERE `ID` = 1486 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Пока Наралекс погружался в свои кошмары все глубже, из-под Степей в Пещеры Стенаний пришли какие-то странные животные.$b$bЭти искаженные существа наделены странными, потусторонними силами. В то время как зло в их природе, я уверен, что из их существования можно извлечь некоторую пользу здесь в Калимдоре. Я верю, что из их кожи наши кожевники смастерят что-нибудь стоящее.$b$bЕсли эта задача тебе по вкусу, отправляйся в пещеры и принеси мне немного искаженных шкур.' AS BINARY)));
