UPDATE `quest_template_locale` SET `QuestDescription` = 'Я за этой башней уже не первую неделю наблюдаю, $n. Недавно прошла крупная поставка из Сумеречного леса, а вместе с ней явились эти стражи.$b$bКто такие? Мы можем только гадать. Одно я тебе скажу: это не люди.$b$bКак бы то ни было, там был сундук – и, как я полагаю, эта мерзость именно его и охраняет. А ключ от сундука – у того зомби с шипами.$b$bДобудь этот ключ, проберись в башню и выясни, что находится в том сундуке. Находку отнесешь Матиасу.' WHERE `ID` = 2359 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Я за этой башней уже не первую неделю наблюдаю, $n. Недавно прошла крупная поставка из Сумеречного леса, а вместе с ней явились эти стражи.$b$bКто такие? Мы можем только гадать. Одно я тебе скажу: это не люди.$b$bКак бы то ни было, там был сундук – и, как я полагаю, эта мерзость именно его и охраняет. А ключ от сундука – у того зомби с шипами.$b$bДобудь этот ключ, проберись в башню и выясни, что находится в том сундуке. Находку отнесешь Матиасу.' AS BINARY)));
