UPDATE `quest_template_locale` SET `QuestDescription` = 'Орда благодарит тебя за неустанную борьбу с кланом Колкар, но сами кентавры в ярости. Я получил сообщение, что отряд клана Колкар оставил свой дом в Пустошах и прибыл в Степи, движимый местью. Более того, они прямо сейчас подбираются к нам с запада!$B$BВыступи против захватчиков из племени Колкар и положи конец опасности, грозящей Степям. Убивай их, пока не появится их вождь, предводитель Кром\'зар. Одолей его и принеси в доказательство кусок его знамени.$B$BНе подведи меня, $n.' WHERE `ID` = 4021 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Орда благодарит тебя за неустанную борьбу с кланом Колкар, но сами кентавры в ярости. Я получил сообщение, что отряд клана Колкар оставил свой дом в Пустошах и прибыл в Степи, движимый местью. Более того, они прямо сейчас подбираются к нам с запада!$B$BВыступи против захватчиков из племени Колкар и положи конец опасности, грозящей Степям. Убивай их, пока не появится их вождь, предводитель Кром\'зар. Одолей его и принеси в доказательство кусок его знамени.$B$BНе подведи меня, $n.' AS BINARY)));
