UPDATE `quest_template_locale` SET `QuestDescription` = 'Ну-ка, посмотрим, стоил ли принесенный тобой знак отличия таких усилий.$b$bВ городе живет чернокнижник, который уверен, будто я ему полностью доверяю. Он и не подозревает, что мне известно о его предательстве. На самом деле он – предводитель Пылающего Клинка... Однако не торопись вступать с ним в бой. Он нам еще нужен, мы можем использовать его, чтобы навредить нашим врагам.$b$bОтнеси ему этот знак отличия в расселину Теней в Оргриммаре, поговори с ним и проверь, примет ли он тебя за $Gодного:одну; из своих. А потом возвращайся ко мне.', `QuestCompletionLog` = '' WHERE `ID` = 5727 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Ну-ка, посмотрим, стоил ли принесенный тобой знак отличия таких усилий.$b$bВ городе живет чернокнижник, который уверен, будто я ему полностью доверяю. Он и не подозревает, что мне известно о его предательстве. На самом деле он – предводитель Пылающего Клинка... Однако не торопись вступать с ним в бой. Он нам еще нужен, мы можем использовать его, чтобы навредить нашим врагам.$b$bОтнеси ему этот знак отличия в расселину Теней в Оргриммаре, поговори с ним и проверь, примет ли он тебя за $Gодного:одну; из своих. А потом возвращайся ко мне.' AS BINARY)) OR NOT (CAST(`QuestCompletionLog` AS BINARY) <=> CAST('' AS BINARY)));
