UPDATE `quest_template_locale` SET `QuestDescription` = 'Таурен горд тем, что защищает эти земли. Несомненно, ты понимаешь, почему я обеспокоен тем, что здесь, в Каменном Когте, обитает множество гарпий.$B$BКлан Смертельной Ярости – вот откуда берутся все новые и новые гарпии в Калимдоре. Они посягают на жизнь всех и каждого, не давая слабым даже уйти отсюда!$B$BМне нужна твоя помощь в уничтожении гарпий, $n!' WHERE `ID` = 6282 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Таурен горд тем, что защищает эти земли. Несомненно, ты понимаешь, почему я обеспокоен тем, что здесь, в Каменном Когте, обитает множество гарпий.$B$BКлан Смертельной Ярости – вот откуда берутся все новые и новые гарпии в Калимдоре. Они посягают на жизнь всех и каждого, не давая слабым даже уйти отсюда!$B$BМне нужна твоя помощь в уничтожении гарпий, $n!' AS BINARY)));
