UPDATE `quest_template_locale` SET `QuestDescription` = 'Жадность промышленников и постоянная война опустошили земли Каменного Пика. Только благословение Матери-Земли может исцелить такие раны.$B$B$n, я хочу отправить тебя на поиски особого семени – семени Геи. Его можно найти только здесь, в Каменном Когте, к северу от Приюта у Солнечного Камня, у Мутного Озера, у самого края воды. $B$BКак только ты принесешь мне эти семена, я напитаю их шаманской силой, дабы ускорить их рост.' WHERE `ID` = 6301 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Жадность промышленников и постоянная война опустошили земли Каменного Пика. Только благословение Матери-Земли может исцелить такие раны.$B$B$n, я хочу отправить тебя на поиски особого семени – семени Геи. Его можно найти только здесь, в Каменном Когте, к северу от Приюта у Солнечного Камня, у Мутного Озера, у самого края воды. $B$BКак только ты принесешь мне эти семена, я напитаю их шаманской силой, дабы ускорить их рост.' AS BINARY)));
