UPDATE `quest_template_locale` SET `QuestDescription` = 'Совет Приливов послал меня объявить войну элементалям огня здесь, в Каменном Когте. Нептулон Приливный Охотник, повелитель всех элементалей воды, лично заинтересован в том, чтобы узреть погибель всех наших огненных сородичей.$B$B$n, ты можешь помочь мне высоко подняться во мнении Совета путем уничтожения элементалей огня в Обугленной долине. После смерти от этих элементалей остаются огненные кристаллы. Отдай их мне, и ты получишь награду.' WHERE `ID` = 6393 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Совет Приливов послал меня объявить войну элементалям огня здесь, в Каменном Когте. Нептулон Приливный Охотник, повелитель всех элементалей воды, лично заинтересован в том, чтобы узреть погибель всех наших огненных сородичей.$B$B$n, ты можешь помочь мне высоко подняться во мнении Совета путем уничтожения элементалей огня в Обугленной долине. После смерти от этих элементалей остаются огненные кристаллы. Отдай их мне, и ты получишь награду.' AS BINARY)));
