UPDATE `quest_template_locale` SET `QuestDescription` = 'В начале туннелей Непроглядной Пучины по стенам пещер можно найти большие сапфировые друзы. Недавно было замечено, что эти кристаллы собирают наги. Пока не станет ясно, зачем им это, сдается мне, что надо наг этой возможности лишить. В кристаллах этих содержится великая сила стихий, и если их применить не как должно, то они могут стать мощным чародейским ингредиентом.$B$BТы мне не поможешь, $n? Непроглядная Пучина находится на Зорамском взморье к северу от нашей заставы.' WHERE `ID` = 6563 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('В начале туннелей Непроглядной Пучины по стенам пещер можно найти большие сапфировые друзы. Недавно было замечено, что эти кристаллы собирают наги. Пока не станет ясно, зачем им это, сдается мне, что надо наг этой возможности лишить. В кристаллах этих содержится великая сила стихий, и если их применить не как должно, то они могут стать мощным чародейским ингредиентом.$B$BТы мне не поможешь, $n? Непроглядная Пучина находится на Зорамском взморье к северу от нашей заставы.' AS BINARY)));
